package com.leetcode.backend.controller;
import com.leetcode.backend.dto.*; import com.leetcode.backend.service.AssessmentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/assessments") public class AssessmentController {private final AssessmentService service;AssessmentController(AssessmentService s){service=s;}@GetMapping public List<Map<String,Object>> list(Authentication a){return service.discover(a.getName());}@GetMapping("/mine") public List<Map<String,Object>> mine(Authentication a){return service.mine(a.getName());}@GetMapping("/{id}") public Map<String,Object> get(Authentication a,@PathVariable Long id){return service.get(a.getName(),id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> create(Authentication a,@Valid @RequestBody AssessmentRequest r){return service.create(a.getName(),r);}@PutMapping("/{id}") public Map<String,Object> update(Authentication a,@PathVariable Long id,@Valid @RequestBody AssessmentRequest r){return service.update(a.getName(),id,r);}@PostMapping("/{id}/publish") public Map<String,Object> publish(Authentication a,@PathVariable Long id){return service.publish(a.getName(),id);}@PostMapping("/{id}/remove-history") @ResponseStatus(HttpStatus.NO_CONTENT) public void removeFromHistory(Authentication a,@PathVariable Long id){service.removeFromHistory(a.getName(),id);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void cancel(Authentication a,@PathVariable Long id){service.cancel(a.getName(),id);}@PostMapping("/{id}/invitations") public Map<String,Object> invite(Authentication a,@PathVariable Long id,@Valid @RequestBody AssessmentInvitationRequest b){return service.invite(a.getName(),id,b.userIds(),b.emails());}@DeleteMapping("/{id}/invitations/{userId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void removeInvitee(Authentication a,@PathVariable Long id,@PathVariable Long userId){service.removeInvitee(a.getName(),id,userId);}@GetMapping("/{id}/analytics") public Map<String,Object> analytics(Authentication a,@PathVariable Long id){boolean admin=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));return service.analytics(a.getName(),id,admin);}@GetMapping("/{id}/leaderboard") public Object leaderboard(Authentication a,@PathVariable Long id){return service.analytics(a.getName(),id,a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"))).get("leaderboard");}}
@RestController @RequestMapping("/api/assessments") class AssessmentCreatorOperationsController {private final AssessmentService service;AssessmentCreatorOperationsController(AssessmentService s){service=s;}@GetMapping("/invitee-search") public List<Map<String,Object>> search(Authentication a,@RequestParam String query){return service.searchInvitees(a.getName(),query);}@GetMapping("/{id}/participants") public List<Map<String,Object>> participants(Authentication a,@PathVariable Long id){return service.participants(a.getName(),id);}}
